      (Fp : Z) (flags : word) (wpos wbase wfn bufp fd : Z) (mode : word) (lbf : Z) (tail : list byte) (S l lo : Z),
    rw_cells asegs m Fp (file_cells flags 0 wpos wbase wfn bufp 0 fd mode lbf tail) ->
